    42  struct contour_point_t
    43  {
    44    void init (float x_ = 0.f, float y_ = 0.f, bool is_end_point_ = false)
    45    { flag = 0; x = x_; y = y_; is_end_point = is_end_point_; }
    46
    47    void translate (const contour_point_t &p) { x += p.x; y += p.y; }
    48
    49    uint8_t flag;
    50    float x, y;
    51    bool is_end_point;
    52  };
    53
    54  struct contour_point_vector_t : hb_vector_t<contour_point_t>
    55  {
    56    void extend (const hb_array_t<contour_point_t> &a)
    57    {
    58      unsigned int old_len = length;
    59      resize (old_len + a.length);
    60      for (unsigned int i = 0; i < a.length; i++)
    61        (*this)[old_len + i] = a[i];
    62    }
    63
    64    void transform (const float (&matrix)[4])
    65    {
    66      for (unsigned int i = 0; i < length; i++)
    67      {
    68        contour_point_t &p = (*this)[i];
    69        float x_ = p.x * matrix[0] + p.y * matrix[2];
    70             p.y = p.x * matrix[1] + p.y * matrix[3];
    71        p.x = x_;
    72      }
    73    }
    74
    75    void translate (const contour_point_t& delta)
    76    {
    77      for (unsigned int i = 0; i < length; i++)
    78        (*this)[i].translate (delta);
    79    }
    80  };
