    82  struct Tuple : UnsizedArrayOf<F2DOT14> {};
    83
    84  struct TuppleIndex : HBUINT16
    85  {
    86    enum Flags {
    87      EmbeddedPeakTuple   = 0x8000u,
    88      IntermediateRegion  = 0x4000u,
    89      PrivatePointNumbers = 0x2000u,
    90      TupleIndexMask      = 0x0FFFu
    91    };
    92
    93    DEFINE_SIZE_STATIC (2);
    94  };
