    96  struct TupleVarHeader
    97  {
    98    unsigned int get_size (unsigned int axis_count) const
    99    {
   100      return min_size +
   101             (has_peak () ? get_peak_tuple ().get_size (axis_count) : 0) +
   102             (has_intermediate () ? (get_start_tuple (axis_count).get_size (axis_count) +
   103                                     get_end_tuple (axis_count).get_size (axis_count)) : 0);
   104    }
   105
   106    const TupleVarHeader &get_next (unsigned int axis_count) const
   107    { return StructAtOffset<TupleVarHeader> (this, get_size (axis_count)); }
   108
   109    float calculate_scalar (const int *coords, unsigned int coord_count,
   110                            const hb_array_t<const F2DOT14> shared_tuples) const
   111    {
   112      const F2DOT14 *peak_tuple;
   113
   114      if (has_peak ())
   115        peak_tuple = &(get_peak_tuple ()[0]);
   116      else
   117      {
   118        unsigned int index = get_index ();
   119        if (unlikely (index * coord_count >= shared_tuples.length))
   120          return 0.f;
   121        peak_tuple = &shared_tuples[coord_count * index];
   122      }
   123
   124      const F2DOT14 *start_tuple = nullptr;
   125      const F2DOT14 *end_tuple = nullptr;
   126      if (has_intermediate ())
   127      {
   128        start_tuple = get_start_tuple (coord_count);
   129        end_tuple = get_end_tuple (coord_count);
   130      }
   131
   132      float scalar = 1.f;
   133      for (unsigned int i = 0; i < coord_count; i++)
   134      {
   135        int v = coords[i];
   136        int peak = peak_tuple[i];
   137        if (!peak || v == peak) continue;
   138
   139        if (has_intermediate ())
   140        {
   141          int start = start_tuple[i];
   142          int end = end_tuple[i];
   143          if (unlikely (start > peak || peak > end ||
   144                        (start < 0 && end > 0 && peak))) continue;
   145          if (v < start || v > end) return 0.f;
   146          if (v < peak)
   147          { if (peak != start) scalar *= (float) (v - start) / (peak - start); }
   148          else
   149          { if (peak != end) scalar *= (float) (end - v) / (end - peak); }
   150        }
   151        else if (!v || v < hb_min (0, peak) || v > hb_max (0, peak)) return 0.f;
   152        else
   153          scalar *= (float) v / peak;
   154      }
   155      return scalar;
   156    }
   157
   158    unsigned int get_data_size () const { return varDataSize; }
   159
   160    bool           has_peak () const { return (tupleIndex & TuppleIndex::EmbeddedPeakTuple); }
   161    bool   has_intermediate () const { return (tupleIndex & TuppleIndex::IntermediateRegion); }
   162    bool has_private_points () const { return (tupleIndex & TuppleIndex::PrivatePointNumbers); }
   163    unsigned int  get_index () const { return (tupleIndex & TuppleIndex::TupleIndexMask); }
   164
   165    protected:
   166    const Tuple &get_peak_tuple () const
   167    { return StructAfter<Tuple> (tupleIndex); }
   168    const Tuple &get_start_tuple (unsigned int axis_count) const
   169    { return *(const Tuple *) &get_peak_tuple ()[has_peak () ? axis_count : 0]; }
   170    const Tuple &get_end_tuple (unsigned int axis_count) const
   171    { return *(const Tuple *) &get_peak_tuple ()[has_peak () ? (axis_count * 2) : axis_count]; }
   172
   173    HBUINT16              varDataSize;
   174    TuppleIndex           tupleIndex;
   175    /* UnsizedArrayOf<F2DOT14> peakTuple - optional */
   176    /* UnsizedArrayOf<F2DOT14> intermediateStartTuple - optional */
   177    /* UnsizedArrayOf<F2DOT14> intermediateEndTuple - optional */
   178
   179    public:
   180    DEFINE_SIZE_MIN (4);
   181  };
