   183  struct TupleVarCount : HBUINT16
   184  {
   185    bool has_shared_point_numbers () const { return ((*this) & SharedPointNumbers); }
   186    unsigned int get_count () const { return (*this) & CountMask; }
   187
   188    protected:
   189    enum Flags
   190    {
   191      SharedPointNumbers  = 0x8000u,
   192      CountMask           = 0x0FFFu
   193    };
   194
   195    public:
   196    DEFINE_SIZE_STATIC (2);
   197  };
